const illo=new Zdog.Illustration({element:'.zdog-svg',zoom:1,rotate:{x:-0.2,y:0.3}});
const purple='#8a4fc4',dark='#402060';
function T(x,z,c){return new Zdog.Shape({addTo:illo,stroke:22,color:purple,closed:false,fill:false,path:[{x:x,y:10,z:z},{bezier:[{x:x+c*10,y:70,z:z},{x:x+c*50,y:80,z:z+20},{x:x+c*40,y:120,z:z+30}]},{bezier:[{x:x+c*10,y:150,z:z+40},{x:x-c*20,y:150,z:z+50},{x:x-c*10,y:120,z:z+30}]}]});}
T(-110,-40,-1);T(110,-40,1);T(-50,-60,1);T(50,-60,-1);
new Zdog.Hemisphere({addTo:illo,translate:{y:-20},rotate:{x:Zdog.TAU/4},diameter:160,color:purple,backface:dark,stroke:false});
T(-80,30,-1);T(0,40,1);T(80,30,1);
[-35,35].forEach(x=>{
new Zdog.Ellipse({addTo:illo,translate:{x:x,y:-35,z:62},diameter:44,stroke:false,fill:true,color:'#fff'});
new Zdog.Shape({addTo:illo,translate:{x:x,y:-33,z:70},stroke:18,color:'#111'});
});
illo.updateRenderGraph();
